template <int kBlocksPerMatrix, int kN, int kColumnsPerTile>
__global__ void reorthogonalize_clustered_subspace_tile(
    const float* __restrict__ localized_values,
    float* __restrict__ vectors, int tile_start) {
  constexpr int n = kN;
  constexpr int kWarpsPerCluster = kBlocksPerMatrix * 8;
  __shared__ float warp_sums[8];
  __shared__ float local_scalars[kWarpsPerCluster + 8];
  cg::cluster_group cluster = cg::this_cluster();
  const int tid = static_cast<int>(threadIdx.x);
  const int cta = static_cast<int>(cluster.block_rank());
  const int cluster_tid = cta * static_cast<int>(blockDim.x) + tid;
  const int cluster_warp = cluster_tid >> 5;
  const int lane = cluster_tid & 31;
  const int matrix = static_cast<int>(blockIdx.x) / kBlocksPerMatrix;
  const int64_t value_offset = static_cast<int64_t>(matrix) * n;
  const int64_t matrix_offset = value_offset * n;
  float* scalars = cluster.map_shared_rank(local_scalars, 0);

  if (cta == 0 && tid == 0) {
    float scale = 0.0f;
    for (int column = 0; column < n; ++column) {
      scale = fmaxf(scale, fabsf(localized_values[value_offset + column]));
    }
    scalars[kWarpsPerCluster + 4] =
        16.0f * FLT_EPSILON * (1.0f + scale);
  }
  cluster.sync();

  const int tile_end = min(n, tile_start + kColumnsPerTile);
  for (int column = tile_start; column < tile_end; ++column) {
    if (cta == 0 && tid == 0) {
      const float threshold = scalars[kWarpsPerCluster + 4];
      int cluster_start = column;
      while (cluster_start > 0 &&
             fabsf(localized_values[value_offset + cluster_start] -
                   localized_values[value_offset + cluster_start - 1]) <=
                 threshold) {
        --cluster_start;
      }
      cluster_start = max(cluster_start, column - 16);
      int cluster_end = column;
      while (cluster_end + 1 < n &&
             fabsf(localized_values[value_offset + cluster_end + 1] -
                   localized_values[value_offset + cluster_end]) <=
                 threshold) {
        ++cluster_end;
      }
      scalars[kWarpsPerCluster + 1] =
          static_cast<float>(cluster_start);
      scalars[kWarpsPerCluster + 2] = static_cast<float>(cluster_end);
    }
    cluster.sync();
    const int cluster_start =
        static_cast<int>(scalars[kWarpsPerCluster + 1]);
    const int cluster_end =
        static_cast<int>(scalars[kWarpsPerCluster + 2]);
    if (cluster_end > cluster_start) {
      for (int sweep = 0; sweep < 1; ++sweep) {
      for (int first = cluster_start; first < column;
           first += kWarpsPerCluster) {
