template <int kEigenvaluesPerBlock, int kN, int kBisectionIterations = 24>
__global__ void tridiagonal_eigenvalues(
    const float* __restrict__ input_diagonal,
    const float* __restrict__ input_off_diagonal,
    float* __restrict__ values, int* __restrict__ info) {
  constexpr int n = kN;
  extern __shared__ float shared[];
  float* d = shared;
  float* e = d + n;
  float* e_squared = e + n;
  __shared__ float lower_bounds[kEigenvaluesPerBlock];
  __shared__ float upper_bounds[kEigenvaluesPerBlock];

  const int tid = static_cast<int>(threadIdx.x);
  const int tiles_per_matrix =
      (n + kEigenvaluesPerBlock - 1) / kEigenvaluesPerBlock;
  const int matrix = static_cast<int>(blockIdx.x) / tiles_per_matrix;
  const int tile = static_cast<int>(blockIdx.x) % tiles_per_matrix;
  const int eigen_index = tile * kEigenvaluesPerBlock + tid;
  const int64_t vector_offset = static_cast<int64_t>(matrix) * n;
  for (int index = tid; index < n; index += blockDim.x) {
    d[index] = input_diagonal[vector_offset + index];
    e[index] = input_off_diagonal[vector_offset + index];
    e_squared[index] = e[index] * e[index];
  }
  __syncthreads();

  float local_low = FLT_MAX;
  float local_high = -FLT_MAX;
  for (int index = tid; index < n; index += blockDim.x) {
    const float radius = (index ? fabsf(e[index - 1]) : 0.0f) +
        (index + 1 < n ? fabsf(e[index]) : 0.0f);
    local_low = fminf(local_low, d[index] - radius);
    local_high = fmaxf(local_high, d[index] + radius);
  }
  lower_bounds[tid] = local_low;
  upper_bounds[tid] = local_high;
  __syncthreads();
  for (int stride = blockDim.x / 2; stride; stride >>= 1) {
    if (tid < stride) {
      lower_bounds[tid] = fminf(lower_bounds[tid], lower_bounds[tid + stride]);
      upper_bounds[tid] = fmaxf(upper_bounds[tid], upper_bounds[tid + stride]);
    }
    __syncthreads();
  }
  const float global_low = lower_bounds[0];
  const float global_high = upper_bounds[0];
  if (tid == 0 && tile == 0) {
    info[matrix] = 0;
  }

  if (eigen_index < n) {
    const float margin = 8.0f * FLT_EPSILON *
        (1.0f + fmaxf(fabsf(global_low), fabsf(global_high)));
    const float pivot_min = 1.0e-20f *
        (1.0f + global_high - global_low);
    float low = global_low - margin;
    float high = global_high + margin;
    for (int iteration = 0; iteration < kBisectionIterations; ++iteration) {
      const float midpoint = 0.5f * (low + high);
      float pivot = d[0] - midpoint;
      if (fabsf(pivot) < pivot_min) {
        pivot = -pivot_min;
      }
      int count = pivot < 0.0f;
      for (int row = 1; row < n; ++row) {
        pivot = d[row] - midpoint - e_squared[row - 1] / pivot;
        if (fabsf(pivot) < pivot_min) {
          pivot = -pivot_min;
        }
        count += pivot < 0.0f;
      }
      if (count <= eigen_index) {
        low = midpoint;
      } else {
        high = midpoint;
      }
    }
    values[vector_offset + eigen_index] = 0.5f * (low + high);
  }
}

template <int kEigenpairsPerBlock, int kVectorPitch, int kN,
          bool kContinue = false>
__global__ void tridiagonal_inverse_iteration(
    const float* __restrict__ input_diagonal,
    const float* __restrict__ input_off_diagonal,
    const float* __restrict__ values, float* __restrict__ vectors) {
  constexpr int n = kN;
  extern __shared__ float shared[];
  float* d = shared;
  float* e = d + n;
  float* tile_vectors = e + n;
  float* tile_factors = tile_vectors + n * kVectorPitch;

  const int tid = static_cast<int>(threadIdx.x);
  const int tiles_per_matrix =
      (n + kEigenpairsPerBlock - 1) / kEigenpairsPerBlock;
  const int matrix = static_cast<int>(blockIdx.x) / tiles_per_matrix;
  const int tile = static_cast<int>(blockIdx.x) % tiles_per_matrix;
  const int eigen_index = tile * kEigenpairsPerBlock + tid;
  const int64_t vector_offset = static_cast<int64_t>(matrix) * n;
  const int64_t matrix_offset = vector_offset * n;
  for (int index = tid; index < n; index += blockDim.x) {
    d[index] = input_diagonal[vector_offset + index];
    e[index] = input_off_diagonal[vector_offset + index];
  }
  __syncthreads();

  if (eigen_index < n) {
    const float eigenvalue = values[vector_offset + eigen_index];
    const float pivot_min = 1.0e-20f * (1.0f + fabsf(eigenvalue));
    float* factors = tile_factors + tid;
    float* eigenvector = tile_vectors + tid;
    for (int row = 0; row < n; ++row) {
      if constexpr (kContinue) {
        eigenvector[row * kVectorPitch] =
            vectors[matrix_offset + row * n + eigen_index];
      } else {
        const int pattern = (row * 17 + eigen_index * 13) % 23;
        eigenvector[row * kVectorPitch] =
            static_cast<float>(pattern - 11) / 11.0f;
      }
    }
    const int inverse_iterations = kContinue ? 1 : 2;
    for (int iteration = 0; iteration < inverse_iterations; ++iteration) {
      const int global_iteration = kContinue ? 1 : iteration;
      const float signed_shift =
          (global_iteration & 1) ? 1.0f : -1.0f;
      const float shifted_value = eigenvalue + signed_shift *
          2.0f * FLT_EPSILON * (1.0f + fabsf(eigenvalue));
      factors[0] = d[0] - shifted_value;
      if (fabsf(factors[0]) < pivot_min) {
        factors[0] = copysignf(pivot_min, factors[0]);
      }
      for (int row = 1; row < n; ++row) {
        const int row_offset = row * kVectorPitch;
        const float multiplier =
            e[row - 1] / factors[row_offset - kVectorPitch];
        factors[row_offset] =
            d[row] - shifted_value - multiplier * e[row - 1];
        if (fabsf(factors[row_offset]) < pivot_min) {
          factors[row_offset] = copysignf(pivot_min, factors[row_offset]);
        }
        eigenvector[row_offset] -=
            multiplier * eigenvector[row_offset - kVectorPitch];
      }
      eigenvector[(n - 1) * kVectorPitch] /=
          factors[(n - 1) * kVectorPitch];
      for (int row = n - 2; row >= 0; --row) {
        const int row_offset = row * kVectorPitch;
        eigenvector[row_offset] =
            (eigenvector[row_offset] -
             e[row] * eigenvector[row_offset + kVectorPitch]) /
            factors[row_offset];
      }
      float norm = 0.0f;
      for (int row = 0; row < n; ++row) {
        const float value = eigenvector[row * kVectorPitch];
        norm += value * value;
      }
      const float inverse_norm = rsqrtf(norm);
      for (int row = 0; row < n; ++row) {
        eigenvector[row * kVectorPitch] *= inverse_norm;
      }
    }
    for (int row = 0; row < n; ++row) {
      vectors[matrix_offset + row * n + eigen_index] =
          eigenvector[row * kVectorPitch];
    }
  }
}

