template <int kEigenpairsPerBlock, int kN, int kBisectionIterations = 25>
__global__ void tridiagonal_eigh_global(
    const float* __restrict__ input_diagonal,
    const float* __restrict__ input_off_diagonal,
    float* __restrict__ values, float* __restrict__ vectors,
    float* __restrict__ factor_workspace, int* __restrict__ info) {
  constexpr int n = kN;
  extern __shared__ float shared[];
  float* d = shared;
  float* e = d + n;
  float* e_squared = e + n;
  __shared__ float lower_bounds[kEigenpairsPerBlock];
  __shared__ float upper_bounds[kEigenpairsPerBlock];

  const int tid = static_cast<int>(threadIdx.x);
  const int tiles_per_matrix =
      (n + kEigenpairsPerBlock - 1) / kEigenpairsPerBlock;
  const int matrix = static_cast<int>(blockIdx.x) / tiles_per_matrix;
  const int tile = static_cast<int>(blockIdx.x) % tiles_per_matrix;
  const int eigen_index = tile * kEigenpairsPerBlock + tid;
  const int64_t vector_offset = static_cast<int64_t>(matrix) * n;
  const int64_t matrix_offset = vector_offset * n;
  for (int index = tid; index < n; index += blockDim.x) {
    d[index] = input_diagonal[vector_offset + index];
    e[index] = input_off_diagonal[vector_offset + index];
    e_squared[index] = e[index] * e[index];
