        pivot = d[row] - midpoint - __fdividef(e_squared[row - 1], pivot);
        if (fabsf(pivot) < bisection_pivot_min) {
          pivot = -bisection_pivot_min;
        }
        count += pivot < 0.0f;
      }
      if (count <= eigen_index) {
        low = midpoint;
      } else {
        high = midpoint;
      }
    }
    const float eigenvalue = 0.5f * (low + high);
    values[vector_offset + eigen_index] = eigenvalue;
    const float pivot_min = 1.0e-20f * (1.0f + fabsf(eigenvalue));
    float* factors = factor_workspace + matrix_offset + eigen_index;
    float* eigenvector = vectors + matrix_offset + eigen_index;
    for (int row = 0; row < n; ++row) {
