template <int kBlocksPerMatrix, int kN, int kColumnsPerTile>
__global__ void reorthogonalize_clustered_subspace_tile(
    const float* __restrict__ localized_values,
    float* __restrict__ vectors, int tile_start) {
  constexpr int n = kN;
  constexpr int kWarpsPerCluster = kBlocksPerMatrix * 8;
  __shared__ float warp_sums[8];
  __shared__ float local_scalars[kWarpsPerCluster + 8];
  cg::cluster_group cluster = cg::this_cluster();
  const int tid = static_cast<int>(threadIdx.x);
  const int cta = static_cast<int>(cluster.block_rank());
  const int cluster_tid = cta * static_cast<int>(blockDim.x) + tid;
  const int cluster_warp = cluster_tid >> 5;
  const int lane = cluster_tid & 31;
  const int matrix = static_cast<int>(blockIdx.x) / kBlocksPerMatrix;
  const int64_t value_offset = static_cast<int64_t>(matrix) * n;
  const int64_t matrix_offset = value_offset * n;
  float* scalars = cluster.map_shared_rank(local_scalars, 0);

  if (cta == 0 && tid == 0) {
    float scale = 0.0f;
    for (int column = 0; column < n; ++column) {
      scale = fmaxf(scale, fabsf(localized_values[value_offset + column]));
    }
    scalars[kWarpsPerCluster + 4] =
        16.0f * FLT_EPSILON * (1.0f + scale);
  }
  cluster.sync();

  const int tile_end = min(n, tile_start + kColumnsPerTile);
  for (int column = tile_start; column < tile_end; ++column) {
    if (cta == 0 && tid == 0) {
      const float threshold = scalars[kWarpsPerCluster + 4];
      int cluster_start = column;
      while (cluster_start > 0 &&
             fabsf(localized_values[value_offset + cluster_start] -
                   localized_values[value_offset + cluster_start - 1]) <=
                 threshold) {
        --cluster_start;
      }
      cluster_start = max(cluster_start, column - 16);
      int cluster_end = column;
      while (cluster_end + 1 < n &&
             fabsf(localized_values[value_offset + cluster_end + 1] -
                   localized_values[value_offset + cluster_end]) <=
                 threshold) {
        ++cluster_end;
      }
      scalars[kWarpsPerCluster + 1] =
          static_cast<float>(cluster_start);
      scalars[kWarpsPerCluster + 2] = static_cast<float>(cluster_end);
    }
    cluster.sync();
    const int cluster_start =
        static_cast<int>(scalars[kWarpsPerCluster + 1]);
    const int cluster_end =
        static_cast<int>(scalars[kWarpsPerCluster + 2]);
    if (cluster_end > cluster_start) {
      for (int sweep = 0; sweep < 1; ++sweep) {
      for (int first = cluster_start; first < column;
           first += kWarpsPerCluster) {
        const int previous = first + cluster_warp;
        float dot = 0.0f;
        if (previous < column) {
          for (int row = lane; row < n; row += 32) {
            dot += vectors[matrix_offset + row * n + previous] *
                vectors[matrix_offset + row * n + column];
          }
        }
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
          dot += __shfl_down_sync(0xffffffff, dot, offset);
        }
        if (lane == 0) {
          scalars[cluster_warp] = dot;
        }
        cluster.sync();
        if (cluster_tid < n) {
          float projection = 0.0f;
          const int count = min(kWarpsPerCluster, column - first);
          #pragma unroll
          for (int index = 0; index < kWarpsPerCluster; ++index) {
            if (index < count) {
              projection += scalars[index] *
                  vectors[matrix_offset + cluster_tid * n + first + index];
            }
          }
          vectors[matrix_offset + cluster_tid * n + column] -= projection;
        }
        cluster.sync();
      }

      float norm = 0.0f;
      if (cluster_tid < n) {
        const float value =
            vectors[matrix_offset + cluster_tid * n + column];
        norm = value * value;
      }
      const float block_norm = block_sum_leader(norm, warp_sums);
      if (tid == 0) {
        scalars[cta] = block_norm;
      }
      cluster.sync();
      if (cta == 0 && tid == 0) {
        float norm_sum = 0.0f;
        #pragma unroll
        for (int block = 0; block < kBlocksPerMatrix; ++block) {
          norm_sum += scalars[block];
        }
        scalars[kWarpsPerCluster] =
            norm_sum > 1.0e-30f ? rsqrtf(norm_sum) : 0.0f;
      }
      cluster.sync();
      if (cluster_tid < n) {
        vectors[matrix_offset + cluster_tid * n + column] *=
            scalars[kWarpsPerCluster];
      }
        cluster.sync();
      }
    }
    cluster.sync();
  }
}

template <int kN>
__global__ void clustered_rayleigh_quotients(
    const float* __restrict__ diagonal,
    const float* __restrict__ off_diagonal,
    const float* __restrict__ localized_values,
    const float* __restrict__ vectors, float* __restrict__ values) {
  constexpr int n = kN;
  extern __shared__ float reduction[];
  const int tid = static_cast<int>(threadIdx.x);
  const int matrix = static_cast<int>(blockIdx.x) / n;
  const int column = static_cast<int>(blockIdx.x) - matrix * n;
  const int64_t value_offset = static_cast<int64_t>(matrix) * n;
  const int64_t matrix_offset = value_offset * n;

  float local_scale = 0.0f;
  for (int index = tid; index < n; index += blockDim.x) {
    local_scale = fmaxf(
        local_scale, fabsf(localized_values[value_offset + index]));
  }
  reduction[tid] = local_scale;
  __syncthreads();
  for (int stride = blockDim.x / 2; stride; stride >>= 1) {
    if (tid < stride) {
      reduction[tid] = fmaxf(reduction[tid], reduction[tid + stride]);
    }
    __syncthreads();
  }
  const float threshold =
      16.0f * FLT_EPSILON * (1.0f + reduction[0]);
  const bool clustered =
      (column > 0 &&
       fabsf(localized_values[value_offset + column] -
             localized_values[value_offset + column - 1]) <= threshold) ||
      (column + 1 < n &&
       fabsf(localized_values[value_offset + column + 1] -
             localized_values[value_offset + column]) <= threshold);
  if (!clustered) {
    return;
  }

  float rayleigh = 0.0f;
  for (int row = tid; row < n; row += blockDim.x) {
    const float value = vectors[matrix_offset + row * n + column];
    rayleigh += diagonal[value_offset + row] * value * value;
    if (row + 1 < n) {
      rayleigh += 2.0f * off_diagonal[value_offset + row] * value *
          vectors[matrix_offset + (row + 1) * n + column];
    }
  }
  reduction[tid] = rayleigh;
  __syncthreads();
  for (int stride = blockDim.x / 2; stride; stride >>= 1) {
    if (tid < stride) {
      reduction[tid] += reduction[tid + stride];
    }
    __syncthreads();
  }
  if (tid == 0) {
    values[value_offset + column] = reduction[0];
  }
}

