  const int tid = static_cast<int>(threadIdx.x);
  const int matrix = static_cast<int>(blockIdx.x) / blocks_per_matrix;
  const int matrix_block = static_cast<int>(blockIdx.x) % blocks_per_matrix;
  if (matrix >= batch) {
    return;
  }

  const int64_t vector_offset = static_cast<int64_t>(matrix) * n;
  const int64_t matrix_offset = vector_offset * n;
  float local_maximum = 0.0f;
  for (int column = tid; column < n; column += blockDim.x) {
    local_maximum = fmaxf(
        local_maximum, fabsf(values[vector_offset + column]));
  }
  value_maxima[tid] = local_maximum;
  __syncthreads();
  for (int stride = blockDim.x / 2; stride; stride >>= 1) {
    if (tid < stride) {
      value_maxima[tid] = fmaxf(
          value_maxima[tid], value_maxima[tid + stride]);
    }
    __syncthreads();
  }

  const float value_scale = fmaxf(value_maxima[0], 1.0e-30f);
  const float safety_fraction = n == 512 ? 0.99f : 0.7f;
  const float orthogonal_limit =
      safety_fraction * 100.0f * n * FLT_EPSILON;
  const float eigen_limit =
      safety_fraction * 200.0f * n * FLT_EPSILON * value_scale;
